var t=s=>`<mi>${s}</mi>`,a=s=>`<mo>${s}</mo>`,i={kind:"vitals",show:["hr","map","co"]},r={kind:"abdomen"},n={kind:"paracentesis",mL:5100,albumin:!0},l={kind:"hemorrhage",mL:1300},d={kind:"infuse",fluid:"albumin"},o={drugs:{carvedilol:!0}},h={drugs:{carvedilol:!1}},e=["map","rpp"],c={id:"kidney",level:"advanced",title:"The kidney in cirrhosis",minutes:10,objectives:["Define the abdominal perfusion pressure (MAP \u2212 IAP), and how tense ascites and LVP change it","State when carvedilol is reduced, stopped and restarted: SBP <90, MAP <65 mmHg or HRS-AKI","Name the drugs for HRS-AKI, and the renal assessment before a TIPS"],checks:[["A patient's MAP is 70 mmHg and the IAP is 15 mmHg. Large-volume paracentesis lowers the IAP to 5 mmHg, and the MAP stays at 70 mmHg. What happens to the APP?","It rises from 55 to 65 mmHg, by the 10 mmHg fall in IAP. The MAP did not change, so the paracentesis alone raised the APP."],["When is carvedilol dose-reduced or stopped, and when is it restarted?","With persistently low blood pressure (systolic <90 mmHg or MAP <65 mmHg) or HRS-AKI. It is restarted once the HRS-AKI has resolved or the blood pressure has recovered (Baveno VIII 4.6, 4.7)."],["Which drug treats HRS-AKI, how is it given, and what is the alternative?","Terlipressin with albumin, preferably as a continuous IV infusion starting at 2 to 3 mg/24 h. Norepinephrine if terlipressin is unavailable, contraindicated or not tolerated (Baveno VIII 6.18 to 6.20)."],["Why can the APP not stand in for a renal assessment before a TIPS for ascites?","The APP is only a pressure, with no normal range and no filtration behind it. Baveno VIII 6.9 asks for renal function to be assessed and chronic kidney disease staged by eGFR for risk stratification."]],summary:"Why the abdominal perfusion pressure is the MAP minus the intra-abdominal pressure and not a measure of kidney function, how tense ascites, large-volume paracentesis, carvedilol and hemorrhage change it, and the Baveno VIII steps for HRS-AKI and before a TIPS.",slides:[{id:"arteries",preset:"cirr-decomp",cam:"fit",tool:i,vignette:"A 58-year-old man with alcohol-associated cirrhosis has ascites controlled on spironolactone and furosemide, large esophageal varices and a serum albumin of 2.8 g/dL.",kicker:"Abdominal perfusion pressure",site:"sin",title:"Arterial vasodilation keeps the MAP low in decompensated cirrhosis",cite:"AASLD 2024, Figure 2",line:"His splanchnic and systemic arteries are dilated and underfilled. His heart rate is {hr} and cardiac output {co}, yet his blood pressure is only {map}, with the MAP in parentheses.",notes:"In decompensated cirrhosis the splanchnic and systemic arteries are dilated, the effective arterial blood volume is low and the kidneys retain sodium and water; at a late stage, compensatory renal vasoconstriction produces hepatorenal syndrome (AASLD 2024, introduction and Figure 2). The cardiac output rises to compensate, yet the arterial pressure still falls. Every APP in this talk starts from this MAP. The model has the arterial vasodilation and the low MAP, and no kidneys.",ask:["Why is the MAP low in decompensated cirrhosis although the cardiac output is high?","Arterial vasodilation lowers the systemic vascular resistance by more than the cardiac output rises."]},{id:"pressure",cam:"fit",tool:r,data:"tiles",tiles:["asc","rpp"],key:["rpp"],eq:[t("APP")+a("=")+t("MAP")+a("\u2212")+t("IAP"),"Abdominal perfusion pressure: mean arterial pressure minus intra-abdominal pressure"],caveat:"The APP is a pressure, not kidney function: the model has no GFR, creatinine or urine output, and no guideline gives the APP a normal range.",kicker:"Abdominal perfusion pressure",site:"sin",title:"The abdominal perfusion pressure is the MAP minus the IAP",line:"The intra-abdominal pressure (IAP) is subtracted from the MAP. At a blood pressure of {map}, the abdominal perfusion pressure (APP) is {rpp}.",notes:"The abdominal perfusion pressure is the mean arterial pressure minus the intra-abdominal pressure (APP = MAP \u2212 IAP), the definition of the World Society of the Abdominal Compartment Syndrome (WSACS). In health the IAP is about 5 mmHg and lowers the APP little. The tile is a number only: Baveno VIII gives no cut-off for it, and the WSACS consensus did not support an APP-directed resuscitation target (PMID 23673399), so the tile has no normal or low band. The blood pressure itself keeps Baveno VIII 4.6's lines (systolic <90 mmHg, MAP <65 mmHg). The tile is a pressure, not renal perfusion or kidney function: the model has no glomerular filtration, creatinine or urine output, and it cannot say whether a kidney is injured or recovering.",ask:["The MAP is 80 mmHg and the IAP is 15 mmHg. What is the APP?","65 mmHg: the MAP minus the IAP."]},{id:"tense",params:{diuretics:!1},days:120,ramp:{albumin:[2.8,2.4]},lapse:{seconds:8,from:"On diuretics",to:"Four months off diuretics"},cam:"fit",tool:{kind:"flowtime",clock:"days",lines:["rpp","asc"],keepTiles:!0,title:"APP and ascites over four months"},data:"tiles",tiles:["asc","rpp"],key:["rpp"],delta:"pressure",kicker:"Abdominal perfusion pressure",site:"sin",title:"Tense ascites raises the IAP and lowers the APP",line:"He stops his diuretics. Four months later, {asc} of ascites has accumulated, and the APP falls from {rpp@pressure} to {rpp}.",notes:"The IAP rises with the volume of ascites, and more steeply once the ascites is tense. The MAP falls only slightly, so most of the fall in APP comes from the rise in IAP. In patients, tense ascites also compresses the renal veins and reduces urine output; the model has the pressure only: it does not estimate GFR, show urine output or diagnose HRS-AKI. The serum albumin falls over the four months, as in the Ascites talk.",ask:["The MAP is unchanged and the ascites has increased to 5 L. What happened to the APP, and why?","It fell, because the IAP rose and the APP is the MAP minus the IAP."]},{id:"tap",action:n,cam:"fit",tool:r,data:"tiles",tiles:["asc","rpp"],key:["rpp"],delta:"tense",kicker:"Abdominal perfusion pressure",site:"sin",title:"Large-volume paracentesis raises the APP",cite:"Baveno VIII Table 3",line:"Large-volume paracentesis (LVP) drains the ascites to {asc}, so the IAP falls and the APP rises to {rpp}. Albumin is given with the LVP.",notes:"Draining the ascites returns the IAP to its resting level and raises the APP. Short-term albumin is indicated with large-volume paracentesis (Baveno VIII, Table 3, a statement of earlier Baveno reports that remains valid); without it, LVP can lower the effective arterial blood volume further and cause AKI, which the model does not show. In the model the albumin raises the serum albumin, and the APP follows the IAP. The MAP changes little with the paracentesis.",ask:["Why is albumin given with large-volume paracentesis?","It maintains the effective arterial blood volume, so arterial underfilling does not worsen and AKI is prevented. Baveno VIII Table 3 keeps short-term albumin for large-volume paracentesis."]},{id:"carv",params:o,cam:"fit",data:"tiles",tiles:e,key:["rpp"],delta:"tap",compare:[{label:"No beta-blocker",short:"None",params:h},{label:"Carvedilol",own:!0,params:o}],kicker:"Carvedilol",site:"sin",title:"Carvedilol lowers the MAP, and the APP with it",cite:"Baveno VIII 4.4, 4.6 \xB7 AASLD 2024",line:"Through \u03B11 blockade, carvedilol lowers the arterial as well as the portal pressure. His blood pressure falls to {map} and the APP to {rpp}, with the MAP still {>=65 mmHg}.",notes:"Carvedilol lowers the portal pressure and, through \u03B11 blockade, the arterial pressure. In this case the fall is small, and the MAP stays above the 65 mmHg line of Baveno VIII 4.6. In a patient with a lower baseline MAP, or with hemorrhage or infection, the same fall can take the MAP below 65 mmHg. AASLD 2024 adds that a systolic pressure <90 mmHg may attenuate the survival benefit of a nonselective beta-blocker (NSBB), possibly by lowering renal perfusion and raising the risk of HRS-AKI, and suggests a switch to propranolol or nadolol for a patient whose blood pressure is low on low-dose carvedilol. Carvedilol is the preferred NSBB (Baveno VIII 4.4), so the question is how to use it safely; the next slide gives the rule (Baveno VIII 4.6, 4.7).",ask:["What does carvedilol do to the MAP, and why does that matter for the beta-blocker rule?","It lowers the MAP through \u03B11 blockade. A MAP <65 mmHg is one reason to dose-reduce or stop it (Baveno VIII 4.6), and the APP falls with the MAP."]},{id:"path-carv",cam:"fit",data:"tiles",tiles:e,key:["rpp"],delta:"tap",tool:{kind:"path",of:"holdcarv",short:"Carvedilol path",patient:{held:!1,hrs:!1}},kicker:"Carvedilol",site:"sin",title:"At this MAP, continue carvedilol",line:"His blood pressure is {map}: neither a systolic {<90 mmHg} nor a MAP {<65 mmHg}, and he has no HRS-AKI. The algorithm says to continue carvedilol.",notes:"The Baveno VIII algorithm for carvedilol in decompensated cirrhosis (4.6, 4.7), applied to this case. Carvedilol is dose-reduced or stopped when the blood pressure stays low (systolic <90 mmHg or MAP <65 mmHg) and/or HRS-AKI develops (4.6). It is restarted and re-titrated once the HRS-AKI has resolved and/or the blood pressure has recovered (4.7). His blood pressure is about 112/63 mmHg with a MAP of 79 mmHg, from the model. The model has no kidneys, so HRS-AKI is a fact of the case: he has none. Neither criterion is met, so carvedilol is continued. A patient whose carvedilol is already held and who has recovered on both counts takes the restart branch. The next slide takes the same patient through a large hemorrhage.",ask:["A man on carvedilol has a blood pressure of 115/64 mmHg (MAP 79 mmHg) and no HRS-AKI. What does the algorithm advise?","Continue carvedilol. Dose-reduce or stop it only for a systolic pressure <90 mmHg, a MAP <65 mmHg or HRS-AKI."]},{id:"hold",action:l,cam:"fit",data:"tiles",tiles:e,key:["rpp"],delta:"carv",tool:{kind:"criteria",title:"Carvedilol: reduce, then restart",short:"Carvedilol",lead:"Any one of these.",rule:"Baveno VIII 4.6, 4.7",rows:[{text:"**Systolic pressure**",key:"sbp",op:"<",value:90,cut:"<90 mmHg"},{text:"**Mean arterial pressure**",key:"map",op:"<",value:65,cut:"<65 mmHg"},"**HRS-AKI**"],verdict:"Restart once HRS-AKI resolves or the blood pressure recovers."},kicker:"Carvedilol",site:"sin",title:"Dose-reduce or stop carvedilol when the MAP is <65 mmHg",line:"A large hemorrhage lowers his blood pressure to {map} and the APP to {rpp}. Carvedilol is dose-reduced or stopped, then restarted once the blood pressure recovers.",notes:"Baveno VIII 4.6: carvedilol is dose-reduced or discontinued with persistently low blood pressure (systolic <90 mmHg or MAP <65 mmHg) and/or HRS-AKI. Baveno VIII 4.7: it is re-initiated and/or re-titrated once the HRS-AKI has resolved and/or the blood pressure has recovered. Hemorrhage is one cause of hypotension; infection and overdiuresis are others. The model reads the systolic pressure and the MAP live in the first two rows; it has no HRS-AKI, so that row states the rule only. The hemorrhage stays in the model and carvedilol is still on here; the next slide holds it.",ask:["A man on carvedilol has a MAP of 62 mmHg after a hemorrhage. What do you do with the carvedilol, and when is it restarted?","Dose-reduce or stop it. Restart it once the blood pressure has recovered and any HRS-AKI has resolved."]},{id:"terli",params:{drugs:{carvedilol:!1,terlipressin:!0}},action:[d],cam:"fit",tool:i,data:"tiles",tiles:e,key:["rpp"],delta:"carv",compare:[{label:"Terlipressin",short:"Terli.",own:!0},{label:"No terlipressin",short:"None",params:{drugs:{carvedilol:!1,terlipressin:!1}}}],kicker:"HRS-AKI",site:"sin",title:"Terlipressin with albumin raises the MAP in HRS-AKI",cite:"Baveno VIII 6.18, 6.19, 6.20",line:"Terlipressin with albumin is considered for HRS-AKI, preferably as a continuous infusion from {2 to 3 mg/24 h}; his blood pressure rises to {map}. Norepinephrine, the alternative, is not modeled.",notes:"Baveno VIII 6.18: in HRS-AKI, treatment with terlipressin and albumin should be considered (LoE 1, strong). 6.19: terlipressin is preferably given as a continuous IV infusion, starting at 2 to 3 mg/24 h, to reduce adverse events. Terlipressin constricts the splanchnic and systemic arteries, so the MAP rises; the albumin expands the circulating volume. HRS-AKI is not caused by blood loss, and no blood is given here: Baveno VIII 5.4 transfuses at a hemoglobin <7 g/dL, aiming for 7 to 8 g/dL, and the model's hemoglobin has not fallen that far (it falls over hours as the plasma refills). The tiles compare with the state before the hemorrhage. Carvedilol is held here, which is why the heart rate is slightly higher than on carvedilol. Baveno VIII 6.20: norepinephrine is the alternative if terlipressin is unavailable, contraindicated or not tolerated (LoE 1, strong). The model has terlipressin but no norepinephrine, so there is no norepinephrine button: the other button shows the same infusion without terlipressin, and the norepinephrine alternative is only on the card. AASLD 2021 gives it as a continuous infusion starting at 0.5 mg/h, up to 3 mg/h, usually in an intensive care unit. The model shows the rise in the MAP and the APP and cannot show renal recovery.",ask:["How is terlipressin given in HRS-AKI, and what is given with it?","Preferably as a continuous IV infusion, starting at 2 to 3 mg/24 h, with albumin."]},{id:"confirm",cam:"fit",tool:{kind:"trial",id:"confirm"},data:"tiles",tiles:e,key:["rpp"],kicker:"HRS-AKI",site:"sin",title:"CONFIRM measured whether terlipressin reverses HRS-AKI",line:"The model shows the pressure rise. CONFIRM counted verified reversal of type 1 HRS in adults given terlipressin or placebo, albumin in both arms.",notes:"CONFIRM (Wong, N Engl J Med 2021) randomized 300 adults with type 1 hepatorenal syndrome 2 to 1 to terlipressin or placebo, with albumin recommended in both, for up to 14 days. Verified HRS reversal was 32% (63 of 199) with terlipressin against 17% (17 of 101) with placebo (P = 0.006). Deaths from respiratory disorders by day 90 were 11% (22 of 199) against 2% (2 of 101), so oxygenation and volume status are watched. More reversal did not establish a survival benefit. Baveno VIII 6.18: terlipressin and albumin should be considered. The model has no kidneys: the APP tile is a pressure, not renal function.",ask:["What did CONFIRM show for terlipressin plus albumin, and what was its main risk?","More verified HRS reversal, 32% against 17%, with more deaths from respiratory disorders, 11% against 2%."]},{id:"staging",cam:"fit",data:"tiles",tiles:e,key:["rpp"],tool:{kind:"criteria",title:"Evaluating for a TIPS",short:"Before a TIPS",ticks:!1,lead:"For recurrent or refractory ascites.",rule:"Baveno VIII 6.9",rows:["**Renal function** assessed in every patient","**Chronic kidney disease** staged by eGFR"],verdict:"The CKD stage stratifies the risk."},kicker:"Before a TIPS",site:"sin",title:"Assess renal function before a TIPS for ascites",line:"Before a TIPS for recurrent or refractory ascites, assess renal function in every patient and stage chronic kidney disease by eGFR. The APP cannot do this.",notes:"Baveno VIII 6.9: in patients undergoing evaluation for TIPS for recurrent or refractory ascites, renal function should be systematically assessed and chronic kidney disease staged (eGFR) for risk stratification (LoE 2, strong). The APP tile has no filtration behind it, so it cannot replace the eGFR. Renal function is assessed first because baseline renal dysfunction predicts a worse course after a TIPS. The shunt itself raises venous return and cardiac output, and natriuresis usually improves over weeks, but how a given patient's kidneys and heart respond cannot be predicted from the pressures.",ask:["What renal assessment is needed before a TIPS for refractory ascites?","Renal function in every patient, with chronic kidney disease staged by eGFR for risk stratification."]},{id:"summary",visual:"table",cols:["map","hr","asc","rpp"],asc:!1,vs:"first",rowHead:"State",of:[{id:"arteries",kicker:"Start",title:"Ascites on diuretics"},{id:"tense",kicker:"Tense ascites",title:"Four months off diuretics"},{id:"tap",kicker:"LVP",title:"Paracentesis with albumin"},{id:"carv",kicker:"Drug",title:"Carvedilol"},{id:"hold",kicker:"Hemorrhage",title:"Large hemorrhage on carvedilol"},{id:"terli",kicker:"HRS-AKI",title:"Terlipressin and albumin"}],kicker:"Summary",title:"What changes the abdominal perfusion pressure",line:"The MAP and the IAP set the APP. Large-volume paracentesis and terlipressin raise it; carvedilol and hemorrhage lower it.",notes:"The APP depends on two pressures: the MAP, which arterial vasodilation keeps low and carvedilol and hemorrhage lower further, and the IAP, which tense ascites raises and large-volume paracentesis restores. Terlipressin with albumin raises the MAP. Carvedilol is dose-reduced with a MAP <65 mmHg or HRS-AKI and restarted once these have resolved. Norepinephrine is the alternative to terlipressin, and chronic kidney disease is staged by eGFR before a TIPS. The tile is a pressure and does not measure renal function.",ask:["Which two pressures set the APP, and which treatment in this talk acts on each?","The MAP and the IAP. Terlipressin raises the MAP; large-volume paracentesis lowers the IAP."]}]};export{c as a};
